-- ========================================================================
-- TEMPLE DATA SEED FOR PHPMYADMIN (cPanel MySQL / MariaDB)
-- Database: ayyappa_aradhana
-- ========================================================================

CREATE TABLE IF NOT EXISTS `temples` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `slug` varchar(100) NOT NULL,
  `name` varchar(255) NOT NULL,
  `local_names_json` text DEFAULT NULL,
  `deity_id` varchar(50) NOT NULL,
  `deity_name` varchar(100) DEFAULT NULL,
  `city` varchar(100) NOT NULL,
  `district` varchar(100) DEFAULT NULL,
  `state` varchar(100) NOT NULL,
  `country` varchar(100) NOT NULL DEFAULT 'India',
  `address` varchar(500) DEFAULT NULL,
  `pincode` varchar(20) DEFAULT NULL,
  `latitude` double DEFAULT NULL,
  `longitude` double DEFAULT NULL,
  `thumbnail_url` varchar(500) DEFAULT NULL,
  `hero_image_url` varchar(500) DEFAULT NULL,
  `about` text NOT NULL,
  `history` text DEFAULT NULL,
  `speciality_json` text DEFAULT NULL,
  `timings_json` text DEFAULT NULL,
  `contact_json` text DEFAULT NULL,
  `live_stream_id` varchar(100) DEFAULT NULL,
  `has_live_darshan` tinyint(1) NOT NULL DEFAULT 0,
  `crop_index` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3) ON UPDATE current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `temples_slug_key` (`slug`),
  KEY `temples_deity_id_idx` (`deity_id`),
  KEY `temples_state_idx` (`state`),
  KEY `temples_is_active_idx` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `temples` (`slug`, `name`, `local_names_json`, `deity_id`, `deity_name`, `city`, `district`, `state`, `country`, `address`, `pincode`, `latitude`, `longitude`, `thumbnail_url`, `hero_image_url`, `about`, `history`, `speciality_json`, `timings_json`, `contact_json`, `live_stream_id`, `has_live_darshan`, `crop_index`, `is_active`)
VALUES ('sabarimala', 'Sabarimala Temple', '{"te":"శబరిమల శ్రీ ధర్మశాస్త దేవాలయం","kn":"ಶಬರಿಮಲೆ ಶ್ರೀ ಧರ್ಮಶಾಸ್ತಾ ದೇವಾಲಯ","ta":"சபரிமலை ஸ்ரீ தர்மசாஸ்தா திருக்கோயில்","hi":"सबरीमाला श्री धर्मशास्ता मंदिर","ml":"ശബരിമല ശ്രീ ധർമ്മശാസ്താ ക്ഷേത്രം","en":"Sabarimala Temple"}', 'ayyappa', 'Lord Ayyappa', 'Pathanamthitta', 'Pathanamthitta', 'Kerala', 'India', 'Sannidhanam, Sabarimala, Periyar Tiger Reserve, Pathanamthitta District, Kerala', '689662', 9.4398, 77.0805, 'https://backendapis.saranamayyappa.in/uploads/temples/sabarimala.png', 'https://backendapis.saranamayyappa.in/uploads/temples/sabarimala_hero.png', 'One of the most revered and ancient hill shrines in India dedicated to Lord Ayyappa, located atop 18 sacred hills amidst the lush forests of the Western Ghats in Kerala. Attracting tens of millions of pilgrims annually, Sabarimala is an epitome of secular unity, devotion and spiritual equality where all devotees are addressed as "Swamimargal".', 'According to temple tradition, Lord Ayyappa, the divine child of Shiva and Mohini (Vishnu), vanquished the demoness Mahishi and entered perpetual meditative penance (samadhi) at Sabarimala. The temple deity was traditionally consecrated by sage Lord Parashurama, and revived by the King of Pandalam.', '["Mandala - Makaravilakku season pilgrimage of 41 days of austerities (Vratam)","Pathinettampadi — The 18 sacred gold-plated steps climbed only with Irumudi Kettu","Neyyabhishekam — Sacred ghee abhishekam offered directly to Lord Ayyappa","Darshan of the divine Makara Jyothi on Pongal / Sankranti evening","Harivarasanam lullaby recited every night before closing the temple doors"]', '{"morning":"03:00 AM – 01:00 PM","evening":"03:00 PM – 11:00 PM","special":"Neyyabhishekam: 03:15 AM – 11:30 AM | Harivarasanam: 10:50 PM","notes":"Temple opens during Mandala-Makaravilakku festival and first 5 days of every Malayalam month. Please confirm official dates before planning travel."}', '{"phone":"+91 4735 202048","email":"sabarimalatdb@gmail.com","website":"https://sabarimala.kerala.gov.in"}', 'sabarimala-live', 1, 0, 1)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `local_names_json` = VALUES(`local_names_json`), `about` = VALUES(`about`);

INSERT INTO `temples` (`slug`, `name`, `local_names_json`, `deity_id`, `deity_name`, `city`, `district`, `state`, `country`, `address`, `pincode`, `latitude`, `longitude`, `thumbnail_url`, `hero_image_url`, `about`, `history`, `speciality_json`, `timings_json`, `contact_json`, `live_stream_id`, `has_live_darshan`, `crop_index`, `is_active`)
VALUES ('tirumala', 'Tirumala Tirupati', '{"te":"తిరుమల శ్రీ వేంకటేశ్వర స్వామి దేవాలయం","kn":"ತಿರುಮಲ ಶ್ರೀ ವೆಂಕಟೇಶ್ವರ ಸ್ವಾಮಿ ದೇವಾಲಯ","ta":"திருமலை திருப்பதி ஸ்ரீ வெங்கடேஸ்வரா திருக்கோயில்","hi":"तिरुपति बालाजी श्री वेंकटेश्वर मंदिर","ml":"തിരുമല ശ്രീ വെങ്കിടേശ്വര സ്വാമി ക്ഷേത്രം","en":"Tirumala Tirupati"}', 'venkateswara', 'Lord Venkateswara', 'Tirupati', 'Tirupati', 'Andhra Pradesh', 'India', 'Srivari Sannidhi, Tirumala Hills, Tirupati, Andhra Pradesh', '517504', 13.6833, 79.3472, 'https://backendapis.saranamayyappa.in/uploads/temples/tirumala.png', 'https://backendapis.saranamayyappa.in/uploads/temples/tirumala_hero.png', 'The sacred abode of Kaliyuga Prathyaksha Daivam, Lord Sri Venkateswara (Balaji). Situated on the picturesque Venkatadri, the seventh peak of the sacred Seshachalam hills in Tirumala, it is the most visited religious center in the world known for divine grace and ceaseless spiritual energy.', 'According to temple lore and inscriptions, the temple has ancient origins dating back to the Sangam period, with extensive patronization by Pallava, Chola, Pandya, and Vijayanagara emperors like Sri Krishna Deva Raya, who gilded the sacred Ananda Nilayam vimana in pure gold.', '["Ananda Nilayam — Golden gopuram sanctifying the presiding deity","World-famous Tirupati Laddu GI-tagged prasadam blessed with divine aroma","Daily Srivari Kalyanotsavam and Sahasra Deepalankarana Seva","Head tonsuring (Kalyanakatta) as an offering of devotion and humility","Annual Brahmotsavam drawing millions of devotees worldwide"]', '{"morning":"03:00 AM – 11:30 PM (Continuous Sarva Darshanam)","evening":"Subject to daily sevas and VIP break intervals","special":"Suprabhata Seva: 03:00 AM | Tomala Seva: 03:30 AM | Ekantha Seva: 01:30 AM","notes":"Darshan timings vary on Brahmotsavam and festive holidays. Advance online quota booking via TTD official portal is recommended."}', '{"phone":"+91 877 2277777","email":"helpdesk@tirumala.org","website":"https://www.tirumala.org"}', 'tirumala-live', 1, 1, 1)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `local_names_json` = VALUES(`local_names_json`), `about` = VALUES(`about`);

INSERT INTO `temples` (`slug`, `name`, `local_names_json`, `deity_id`, `deity_name`, `city`, `district`, `state`, `country`, `address`, `pincode`, `latitude`, `longitude`, `thumbnail_url`, `hero_image_url`, `about`, `history`, `speciality_json`, `timings_json`, `contact_json`, `live_stream_id`, `has_live_darshan`, `crop_index`, `is_active`)
VALUES ('srisailam', 'Srisailam Temple', '{"te":"శ్రీశైలం శ్రీ మల్లికార్జున స్వామి దేవస్థానం","kn":"ಶ್ರೀಶೈಲ ಮಲ್ಲಿಕಾರ್ಜುನ ಸ್ವಾಮಿ ದೇವಾಲಯ","ta":"ஸ்ரீசைலம் ஸ்ரீ மல்லிகார்ஜுனர் திருக்கோயில்","hi":"श्रीशैलम श्री मल्लिकार्जुन ज्योतिर्लिंग मंदिर","ml":"ശ്രീശൈലം ശ്രീ മല്ലികാർജ്ജുന ക്ഷേത്രം","en":"Srisailam Temple"}', 'shiva', 'Lord Shiva & Bhramaramba Devi', 'Srisailam', 'Nandyal', 'Andhra Pradesh', 'India', 'Srisailam Devasthanam, Nallamala Hills, Nandyal District, Andhra Pradesh', '518101', 16.0744, 78.8687, 'https://backendapis.saranamayyappa.in/uploads/temples/srisailam.png', 'https://backendapis.saranamayyappa.in/uploads/temples/srisailam_hero.png', 'One of the holiest shrines in India, Srisailam is uniquely revered as both one of the 12 sacred Jyotirlingas of Lord Shiva (Mallikarjuna Swamy) and one of the 18 Maha Shakti Peethas of Goddess Parvati (Bhramaramba Devi).', 'Mentioned extensively in the Mahabharata, Skanda Purana, and historical records of Ikshvaku, Pallava, Vishnukundina, Kakatiya and Vijayanagara dynasties.', '["Rare combined Jyotirlinga and Maha Shakti Peetha pilgrimage site","Sparsha Darshanam — Devotees can directly touch and perform Abhishekam to the sacred Shivalinga","Majestic Patala Ganga ghats nestled on the banks of holy river Krishna","Sacred Shikhareswaram peak offering sweeping panoramic view of the forest hills"]', '{"morning":"04:30 AM – 03:30 PM","evening":"05:30 PM – 10:00 PM","special":"Sparsha Darshanam: 06:00 AM – 03:00 PM (Scheduled batches)","notes":"Temple remains open late on Maha Shivaratri and Karthika Masam days."}', '{"phone":"+91 8524 288888","email":"eo_srisailam@yahoo.com","website":"https://srisailadevasthanam.org"}', 'srisailam-live', 1, 2, 1)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `local_names_json` = VALUES(`local_names_json`), `about` = VALUES(`about`);

INSERT INTO `temples` (`slug`, `name`, `local_names_json`, `deity_id`, `deity_name`, `city`, `district`, `state`, `country`, `address`, `pincode`, `latitude`, `longitude`, `thumbnail_url`, `hero_image_url`, `about`, `history`, `speciality_json`, `timings_json`, `contact_json`, `live_stream_id`, `has_live_darshan`, `crop_index`, `is_active`)
VALUES ('kashi-vishwanath', 'Kashi Vishwanath Temple', '{"te":"కాశీ విశ్వనాథ మందిరం","kn":"ಕಾಶಿ ವಿಶ್ವನಾಥ ದೇವಾಲಯ","ta":"காசி விஸ்வநாதர் திருக்கோயில்","hi":"काशी विश्वनाथ मंदिर वाराणसी","ml":"കാശി വിശ്വനാഥ ക്ഷേത്രം","en":"Kashi Vishwanath Temple"}', 'shiva', 'Lord Shiva', 'Varanasi', 'Varanasi', 'Uttar Pradesh', 'India', 'Vishwanath Gali, Lahori Tola, Varanasi, Uttar Pradesh', '221001', 25.3109, 83.0107, 'https://backendapis.saranamayyappa.in/uploads/temples/kashi-vishwanath.png', 'https://backendapis.saranamayyappa.in/uploads/temples/kashi-vishwanath_hero.png', 'Standing majestically on the western bank of the sacred river Ganga in Varanasi (Kashi), the spiritual capital of India. The temple enshrines the Jyotirlinga of Vishweshwara or Vishwanath — the Ruler of the Universe.', 'Varanasi is widely celebrated as the oldest continuously inhabited sacred city on earth.', '["One of the twelve supreme Jyotirlingas situated along sacred mother Ganga","Grand modern Kashi Vishwanath Dham corridor seamlessly uniting temple and Ganga ghats","Sacred Mangala Aarti performed at 03:00 AM every morning","Belief that death or darshan in Kashi bestows immediate Moksha (liberation)"]', '{"morning":"02:30 AM – 11:00 AM","evening":"12:00 PM – 11:00 PM","special":"Mangala Aarti: 03:00 AM – 04:00 AM | Shringar/Bhog: 11:15 AM | Saptarshi Aarti: 07:00 PM"}', '{"phone":"+91 542 2392629","email":"info@shrikashivishwanath.org","website":"https://shrikashivishwanath.org"}', 'kashi-live', 1, 3, 1)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `local_names_json` = VALUES(`local_names_json`), `about` = VALUES(`about`);

INSERT INTO `temples` (`slug`, `name`, `local_names_json`, `deity_id`, `deity_name`, `city`, `district`, `state`, `country`, `address`, `pincode`, `latitude`, `longitude`, `thumbnail_url`, `hero_image_url`, `about`, `history`, `speciality_json`, `timings_json`, `contact_json`, `live_stream_id`, `has_live_darshan`, `crop_index`, `is_active`)
VALUES ('rameswaram', 'Ramanathaswamy Temple', '{"te":"రామనాథస్వామి దేవాలయం రామేశ్వరం","kn":"ರಾಮನಾಥಸ್ವಾಮಿ ದೇವಾಲಯ ರಾಮೇಶ್ವರಂ","ta":"இராமேஸ்வரம் ஸ்ரீ இராமநாதசுவாமி திருக்கோயில்","hi":"रामेश्वरम श्री रामनाथस्वामी ज्योतिर्लिंग मंदिर","ml":"രാമേശ്വരം രാമനാഥസ്വാമി ക്ഷേത്രം","en":"Ramanathaswamy Temple"}', 'shiva', 'Lord Shiva', 'Rameswaram', 'Ramanathapuram', 'Tamil Nadu', 'India', 'East Car Street, Rameswaram, Ramanathapuram District, Tamil Nadu', '623526', 9.2881, 79.3174, 'https://backendapis.saranamayyappa.in/uploads/temples/rameswaram.png', 'https://backendapis.saranamayyappa.in/uploads/temples/rameswaram_hero.png', 'Located on Pamban Island in Tamil Nadu, this holy pilgrimage is revered as both one of the 12 Jyotirlingas and one of the holy Char Dhams of India. The main deity was consecrated by Sri Rama Himself to atone for Brahmahatya dosha after defeating Ravana.', 'The Shivalinga was fashioned out of seaside sand by Sita Devi (Ramalingam), while Lord Hanuman brought another Linga from Mount Kailasha (Viswalingam).', '["The longest and most majestic carved pillared corridor in any Hindu temple in the world (1212 pillars)","22 Sacred Theerthams (holy wells) inside temple precincts where devotees take holy snanam","Holy Char Dham and Jyotirlinga synthesis","Magnificent Dravidian architecture and seaside spiritual tranquility"]', '{"morning":"05:00 AM – 01:00 PM","evening":"03:00 PM – 09:00 PM","special":"Spadika Linga Darshanam: 05:00 AM – 06:00 AM | Theertha Snanam: 05:00 AM – 12:30 PM"}', '{"phone":"+91 4573 221223","email":"rameswaramtemple@tnhrce.org","website":"https://rameswaramtemple.tnhrce.in"}', 'rameswaram-live', 0, 4, 1)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `local_names_json` = VALUES(`local_names_json`), `about` = VALUES(`about`);

INSERT INTO `temples` (`slug`, `name`, `local_names_json`, `deity_id`, `deity_name`, `city`, `district`, `state`, `country`, `address`, `pincode`, `latitude`, `longitude`, `thumbnail_url`, `hero_image_url`, `about`, `history`, `speciality_json`, `timings_json`, `contact_json`, `live_stream_id`, `has_live_darshan`, `crop_index`, `is_active`)
VALUES ('kedarnath', 'Kedarnath Temple', '{"te":"కేదార్‌నాథ్ మందిరం","kn":"ಕೇದಾರನಾಥ ದೇವಾಲಯ","ta":"கேதார்நாத் திருக்கோயில்","hi":"श्री केदारनाथ धाम ज्योतिर्लिंग","ml":"കേദാർനാഥ് ക്ഷേത്രം","en":"Kedarnath Temple"}', 'shiva', 'Lord Shiva', 'Kedarnath', 'Rudraprayag', 'Uttarakhand', 'India', 'Kedarnath Valley, Rudraprayag District, Garhwal Himalayas, Uttarakhand', '246445', 30.7352, 79.0669, 'https://backendapis.saranamayyappa.in/uploads/temples/kedarnath.png', 'https://backendapis.saranamayyappa.in/uploads/temples/kedarnath_hero.png', 'Perched at a breath-taking altitude of 3,583 meters in the Garhwal Himalayas near the Mandakini river, Kedarnath is the highest of the 12 Jyotirlingas and the foremost of the Panch Kedar shrines.', 'Built by the Pandavas seeking absolution from Lord Shiva after the Kurukshetra war, and subsequently restored and expanded by Adi Shankaracharya in the 8th century CE.', '["Highest among all 12 sacred Jyotirlingas of Lord Shiva","Magnificent 1000-year-old grey stone masonry that survived the devastating 2013 flash floods","Panch Kedar foremost shrine and Chota Char Dham pilgrimage destination","Scenic Himalayan trekking route offering unparalleled spiritual and natural grandeur"]', '{"morning":"04:00 AM – 03:00 PM","evening":"05:00 PM – 09:00 PM","special":"Maha Abhishek: 04:00 AM – 07:00 AM | Shayan Aarti: 08:30 PM","notes":"Temple is open only 6 months a year (Akshaya Tritiya to Diwali / Bhai Dooj). During winter, Utsava Murti shifts to Ukhimath."}', '{"phone":"+91 135 2741600","email":"contact@badrinath-kedarnath.gov.in","website":"https://badrinath-kedarnath.gov.in"}', 'kedarnath-live', 0, 5, 1)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `local_names_json` = VALUES(`local_names_json`), `about` = VALUES(`about`);

INSERT INTO `temples` (`slug`, `name`, `local_names_json`, `deity_id`, `deity_name`, `city`, `district`, `state`, `country`, `address`, `pincode`, `latitude`, `longitude`, `thumbnail_url`, `hero_image_url`, `about`, `history`, `speciality_json`, `timings_json`, `contact_json`, `live_stream_id`, `has_live_darshan`, `crop_index`, `is_active`)
VALUES ('meenakshi-amman', 'Meenakshi Amman Temple', '{"te":"మదురై మీనాక్షి అమ్మవారి దేవాలయం","kn":"ಮಧುರೈ ಮೀನಾಕ್ಷಿ ಅಮ್ಮನವರ ದೇವಾಲಯ","ta":"மதுரை ஸ்ரீ மீனாட்சி சுந்தரேஸ்வரர் திருக்கோயில்","hi":"मदुरै मीनाक्षी अम्मन मंदिर","ml":"മധുര മീനാക്ഷി ക്ഷേത്രം","en":"Meenakshi Amman Temple"}', 'devi', 'Goddess Meenakshi & Sundareswarar', 'Madurai', 'Madurai', 'Tamil Nadu', 'India', 'Madurai Main, Madurai, Tamil Nadu', '625001', 9.9195, 78.1193, 'https://backendapis.saranamayyappa.in/uploads/temples/meenakshi-amman.png', 'https://backendapis.saranamayyappa.in/uploads/temples/meenakshi-amman_hero.png', 'Located in the historic heart of the ancient temple city of Madurai on the banks of river Vaigai. Dedicated to Goddess Meenakshi (an avatar of Parvati) and her consort Sundareswarar (Shiva), it is celebrated as an apex of Dravidian sculpture and devotion.', 'The temple was originally constructed by King Kulasekara Pandya and substantially re-built to its present architectural grandeur during the 16th and 17th centuries by the Nayak rulers, especially Tirumala Nayaka.', '["14 towering Gopurams adorned with thousands of colorful mythological stucco sculptures","Fabulous Ayiram Kaal Mandapam (Hall of 1000 Pillars) with exquisite granite stone carvings","Musical pillars producing the seven Swaras when tapped with fingertips","Golden Lotus Pond (Porthamarai Kulam) revered for literary and spiritual significance"]', '{"morning":"05:00 AM – 12:30 PM","evening":"04:00 PM – 10:00 PM","special":"Palliarai Pooja: 09:30 PM – 10:00 PM nightly procession"}', '{"phone":"+91 452 2344360","email":"meenakshitemple@tnhrce.org","website":"https://maduraimeenakshi.tnhrce.in"}', 'meenakshi-live', 1, 6, 1)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `local_names_json` = VALUES(`local_names_json`), `about` = VALUES(`about`);

INSERT INTO `temples` (`slug`, `name`, `local_names_json`, `deity_id`, `deity_name`, `city`, `district`, `state`, `country`, `address`, `pincode`, `latitude`, `longitude`, `thumbnail_url`, `hero_image_url`, `about`, `history`, `speciality_json`, `timings_json`, `contact_json`, `live_stream_id`, `has_live_darshan`, `crop_index`, `is_active`)
VALUES ('palani', 'Palani Murugan Temple', '{"te":"పళని దండాయుధపాణి స్వామి దేవాలయం","kn":"ಪಳನಿ ದಂಡಾಯುಧಪಾಣಿ ಸ್ವಾಮಿ ದೇವಾಲಯ","ta":"பழனி ஸ்ரீ தண்டாயுதபாணி சுவாமி திருக்கோயில்","hi":"पलानी मुरुगन मंदिर","ml":"പഴനി ദണ്ഡായുಧപാണി ക്ഷേത്രം","en":"Palani Murugan Temple"}', 'murugan', 'Lord Murugan', 'Palani', 'Dindigul', 'Tamil Nadu', 'India', 'Giri Veethi, Sivagiri Hills, Palani, Dindigul District, Tamil Nadu', '624601', 10.4439, 77.5186, 'https://backendapis.saranamayyappa.in/uploads/temples/palani.png', 'https://backendapis.saranamayyappa.in/uploads/temples/palani_hero.png', 'The third and most celebrated among the sacred Arupadaiveedu (six holy abodes of Lord Murugan), situated atop the Sivagiri hill in Palani.', 'Siddha Bogar created the presiding idol of Dhandayuthapani using Navapashanam (a compound of nine miraculous herbal and mineral poisons that cure diseases).', '["Foremost of the six holy Padai Veedu abodes of Lord Murugan","Miraculous Navapashanam idol synthesized by sage Siddha Bogar","World-famous Palani Panchamirtham GI-tagged divine prasadam","Kavadi and Thaipusam festivals drawing millions of ecstatic devotees"]', '{"morning":"05:30 AM – 12:00 PM","evening":"04:00 PM – 09:30 PM","special":"Viswaroopa Darshanam: 06:00 AM | Sayaraksha Pooja: 05:30 PM | Rakkala Pooja: 08:30 PM"}', '{"phone":"+91 4545 242236","email":"palanitemple@tnhrce.org","website":"https://palanimurugan.tnhrce.in"}', 'palani-live', 0, 7, 1)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `local_names_json` = VALUES(`local_names_json`), `about` = VALUES(`about`);

INSERT INTO `temples` (`slug`, `name`, `local_names_json`, `deity_id`, `deity_name`, `city`, `district`, `state`, `country`, `address`, `pincode`, `latitude`, `longitude`, `thumbnail_url`, `hero_image_url`, `about`, `history`, `speciality_json`, `timings_json`, `contact_json`, `live_stream_id`, `has_live_darshan`, `crop_index`, `is_active`)
VALUES ('siddhivinayak', 'Siddhivinayak Temple', '{"te":"సిద్ధివినాయక దేవాలయం ముంబై","kn":"ಸಿದ್ಧಿವಿನಾಯಕ ದೇವಾಲಯ ಮುಂಬೈ","ta":"மும்பை ஸ்ரீ சித்திவிநாயகர் திருக்கோயில்","hi":"सिद्धिविनायक मंदिर मुंबई","ml":"സിദ്ധിവിനായക ക്ഷേത്രം മുംബൈ","en":"Siddhivinayak Temple"}', 'ganesha', 'Lord Ganesha', 'Mumbai', 'Mumbai City', 'Maharashtra', 'India', 'SK Bole Marg, Prabhadevi, Mumbai, Maharashtra', '400028', 19.0169, 72.8304, 'https://backendapis.saranamayyappa.in/uploads/temples/siddhivinayak.png', 'https://backendapis.saranamayyappa.in/uploads/temples/siddhivinayak_hero.png', 'Dedicated to Lord Shri Ganesha, Siddhivinayak in Prabhadevi, Mumbai is one of the richest and most widely visited temples in India.', 'Originally consecrated on 19 November 1801 by Laxman Vithu and Deubai Patil to grant the wish of childless women.', '["Navasacha Ganapati — celebrated throughout India as the fulfiller of all wishes","Unique idol carved out of a single black stone with trunk turning towards the right side","Magnificent gold-plated inner sanctum dome and Ashtavinayak carvings on wooden doors","Lakhs of devotees on Angaraki Chaturthi and Tuesdays walking barefoot for darshan"]', '{"morning":"05:30 AM – 12:15 PM","evening":"03:15 PM – 09:50 PM (Open 03:15 AM to 12:00 Midnight on Tuesdays)","special":"Kakad Aarti: 05:30 AM | Shree Aarti: 12:05 PM | Shejaarti: 09:50 PM"}', '{"phone":"+91 22 24223206","email":"info@siddhivinayak.org","website":"https://www.siddhivinayak.org"}', 'siddhivinayak-live', 1, 8, 1)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `local_names_json` = VALUES(`local_names_json`), `about` = VALUES(`about`);

INSERT INTO `temples` (`slug`, `name`, `local_names_json`, `deity_id`, `deity_name`, `city`, `district`, `state`, `country`, `address`, `pincode`, `latitude`, `longitude`, `thumbnail_url`, `hero_image_url`, `about`, `history`, `speciality_json`, `timings_json`, `contact_json`, `live_stream_id`, `has_live_darshan`, `crop_index`, `is_active`)
VALUES ('guruvayur', 'Guruvayur Temple', '{"te":"గురువాయూర్ శ్రీ కృష్ణ దేవాలయం","kn":"ಗುರುವಾಹೂರು ಶ್ರೀ ಕೃಷ್ಣ ದೇವಾಲಯ","ta":"குருவாயூர் ஸ்ரீ கிருஷ்ணர் திருக்கோயில்","hi":"गुरुवायुर श्री कृष्ण मंदिर","ml":"ഗുരുവായൂർ ശ്രീകൃഷ്ണ ക്ഷേത്രം","en":"Guruvayur Temple"}', 'krishna', 'Lord Krishna (Guruvayurappan)', 'Guruvayur', 'Thrissur', 'Kerala', 'India', 'Guruvayur Devaswom, East Nada, Guruvayur, Thrissur District, Kerala', '680101', 10.5947, 76.0384, 'https://backendapis.saranamayyappa.in/uploads/temples/guruvayur.png', 'https://backendapis.saranamayyappa.in/uploads/temples/guruvayur_hero.png', 'Affectionately known as "Bhooloka Vaikuntham" (abode of Vishnu on Earth), Guruvayur Temple in Kerala is dedicated to Lord Guruvayurappan (the infant form of Lord Krishna).', 'According to tradition, the idol was worshipped by Vasudeva and Devaki and later by Lord Krishna in Dwaraka.', '["Bhooloka Vaikuntham — Divine deity consecrated by Guru (Brihaspati) and Vayu Deva","Udayasthamana Pooja, Seeveli processions with caparisoned temple elephants","Thulabharam offering where devotees offer their weight in bananas, jaggery, or sugar","Punnathur Kotta — World-famous sanctuary sheltering over 40 majestic temple elephants"]', '{"morning":"03:00 AM – 01:30 PM","evening":"04:30 PM – 09:15 PM","special":"Nirmalya Darshanam: 03:00 AM | Ucha Pooja: 12:00 PM | Athazha Pooja: 08:30 PM"}', '{"phone":"+91 487 2556335","email":"guruvayurdevaswom@gmail.com","website":"https://guruvayurdevaswom.in"}', 'guruvayur-live', 1, 9, 1)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `local_names_json` = VALUES(`local_names_json`), `about` = VALUES(`about`);
